/* ==========================================================================
   SEIRI PERÚ — BASE DE DATOS TRANSACCIONAL (SeiriDB)
   Fuente: Factura Peruana (ventas, catálogo, kardex) + archivos de costeo e
   importaciones de Seiri. Periodo: 01/04/2025 – 09/10/2026.
   Datos de clientes anonimizados. Ejecutar completo en SSMS (F5).
   17 tablas · Modelo normalizado (3FN) · Llaves primarias y foráneas
   ========================================================================== */
IF DB_ID('SeiriDB') IS NOT NULL
BEGIN
    ALTER DATABASE SeiriDB SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE SeiriDB;
END
GO
CREATE DATABASE SeiriDB;
GO
USE SeiriDB;
GO

-- Categoria: Categorías de producto definidas por Seiri (prefijo del código)
CREATE TABLE dbo.Categoria (
    IdCategoria INT NOT NULL CONSTRAINT PK_Categoria PRIMARY KEY,
    CodigoCategoria NVARCHAR(5) NOT NULL,
    NombreCategoria NVARCHAR(30) NOT NULL
);
GO

-- Material: Materiales de fabricación, con el código que usa Seiri en la descripción
CREATE TABLE dbo.Material (
    IdMaterial INT NOT NULL CONSTRAINT PK_Material PRIMARY KEY,
    CodigoMaterial NVARCHAR(10) NOT NULL,
    NombreMaterial NVARCHAR(40) NOT NULL
);
GO

-- Origen: De dónde proviene el producto: importación desde China o compra nacional
CREATE TABLE dbo.Origen (
    IdOrigen INT NOT NULL CONSTRAINT PK_Origen PRIMARY KEY,
    CodigoOrigen NVARCHAR(10) NOT NULL,
    NombreOrigen NVARCHAR(40) NOT NULL,
    TipoOrigen NVARCHAR(30) NOT NULL,
    FechaPedido DATE NULL,
    FechaLlegadaAlmacen DATE NULL
);
GO

-- TipoProducto: Tipo de producto según cómo se vende
CREATE TABLE dbo.TipoProducto (
    IdTipoProducto INT NOT NULL CONSTRAINT PK_TipoProducto PRIMARY KEY,
    NombreTipoProducto NVARCHAR(30) NOT NULL
);
GO

-- Producto: Catálogo de productos de Seiri (activos y descontinuados)
CREATE TABLE dbo.Producto (
    IdProducto INT NOT NULL CONSTRAINT PK_Producto PRIMARY KEY,
    CodigoProducto NVARCHAR(20) NOT NULL,
    Descripcion NVARCHAR(150) NOT NULL,
    IdCategoria INT NOT NULL,
    IdMaterial INT NOT NULL,
    IdOrigen INT NOT NULL,
    IdTipoProducto INT NOT NULL,
    TipoBase NVARCHAR(40) NULL,
    Caracteristica NVARCHAR(40) NULL,
    Linea NVARCHAR(40) NULL,
    Capacidad NVARCHAR(30) NULL,
    Medida NVARCHAR(40) NULL,
    Color NVARCHAR(30) NULL,
    UnidadMedida NVARCHAR(15) NOT NULL,
    PrecioAlmacen DECIMAL(12,4) NULL,
    PrecioVenta DECIMAL(12,4) NULL,
    StockMinimo DECIMAL(12,3) NULL,
    StockActual DECIMAL(12,3) NULL,
    Estado NVARCHAR(15) NOT NULL,
    CONSTRAINT FK_Producto_Categoria FOREIGN KEY (IdCategoria) REFERENCES dbo.Categoria(IdCategoria),
    CONSTRAINT FK_Producto_Material FOREIGN KEY (IdMaterial) REFERENCES dbo.Material(IdMaterial),
    CONSTRAINT FK_Producto_Origen FOREIGN KEY (IdOrigen) REFERENCES dbo.Origen(IdOrigen),
    CONSTRAINT FK_Producto_TipoProducto FOREIGN KEY (IdTipoProducto) REFERENCES dbo.TipoProducto(IdTipoProducto),
    CONSTRAINT UQ_Producto_Codigo UNIQUE (CodigoProducto),
    CONSTRAINT CK_Producto_Estado CHECK (Estado IN (N'ACTIVO', N'DESCONTINUADO'))
);
GO

-- Departamento: Departamentos del Perú registrados en las ventas
CREATE TABLE dbo.Departamento (
    IdDepartamento INT NOT NULL CONSTRAINT PK_Departamento PRIMARY KEY,
    NombreDepartamento NVARCHAR(40) NOT NULL
);
GO

-- Provincia: Provincias
CREATE TABLE dbo.Provincia (
    IdProvincia INT NOT NULL CONSTRAINT PK_Provincia PRIMARY KEY,
    NombreProvincia NVARCHAR(40) NOT NULL,
    IdDepartamento INT NOT NULL,
    CONSTRAINT FK_Provincia_Departamento FOREIGN KEY (IdDepartamento) REFERENCES dbo.Departamento(IdDepartamento)
);
GO

-- Distrito: Distritos
CREATE TABLE dbo.Distrito (
    IdDistrito INT NOT NULL CONSTRAINT PK_Distrito PRIMARY KEY,
    NombreDistrito NVARCHAR(40) NOT NULL,
    IdProvincia INT NOT NULL,
    CONSTRAINT FK_Distrito_Provincia FOREIGN KEY (IdProvincia) REFERENCES dbo.Provincia(IdProvincia)
);
GO

-- Cliente: Clientes anonimizados (sin nombre, documento, dirección ni teléfono)
CREATE TABLE dbo.Cliente (
    IdCliente INT NOT NULL CONSTRAINT PK_Cliente PRIMARY KEY,
    CodigoCliente NVARCHAR(15) NOT NULL,
    TipoDocumento NVARCHAR(20) NOT NULL,
    IdDistrito INT NOT NULL,
    FechaRegistro DATE NOT NULL,
    CONSTRAINT FK_Cliente_Distrito FOREIGN KEY (IdDistrito) REFERENCES dbo.Distrito(IdDistrito),
    CONSTRAINT UQ_Cliente_Codigo UNIQUE (CodigoCliente)
);
GO

-- Usuario: Usuarios del sistema de facturación
CREATE TABLE dbo.Usuario (
    IdUsuario INT NOT NULL CONSTRAINT PK_Usuario PRIMARY KEY,
    NombreUsuario NVARCHAR(30) NOT NULL,
    Rol NVARCHAR(20) NOT NULL
);
GO

-- Almacen: Puntos de almacenamiento del inventario
CREATE TABLE dbo.Almacen (
    IdAlmacen INT NOT NULL CONSTRAINT PK_Almacen PRIMARY KEY,
    NombreAlmacen NVARCHAR(40) NOT NULL,
    TipoAlmacen NVARCHAR(30) NOT NULL
);
GO

-- TipoComprobante: Tipos de comprobante de venta
CREATE TABLE dbo.TipoComprobante (
    IdTipoComprobante INT NOT NULL CONSTRAINT PK_TipoComprobante PRIMARY KEY,
    NombreTipoComprobante NVARCHAR(30) NOT NULL,
    Serie NVARCHAR(5) NOT NULL,
    CodigoSunat NVARCHAR(3) NULL
);
GO

-- EstadoComprobante: Estados del comprobante
CREATE TABLE dbo.EstadoComprobante (
    IdEstadoComprobante INT NOT NULL CONSTRAINT PK_EstadoComprobante PRIMARY KEY,
    NombreEstado NVARCHAR(15) NOT NULL
);
GO

-- Venta: Cabecera del comprobante de venta
CREATE TABLE dbo.Venta (
    IdVenta INT NOT NULL CONSTRAINT PK_Venta PRIMARY KEY,
    Serie NVARCHAR(5) NOT NULL,
    NumeroComprobante INT NOT NULL,
    FechaEmision DATE NOT NULL,
    IdCliente INT NOT NULL,
    IdUsuario INT NOT NULL,
    IdTipoComprobante INT NOT NULL,
    IdEstadoComprobante INT NOT NULL,
    TotalComprobante DECIMAL(12,2) NOT NULL,
    CONSTRAINT FK_Venta_Cliente FOREIGN KEY (IdCliente) REFERENCES dbo.Cliente(IdCliente),
    CONSTRAINT FK_Venta_Usuario FOREIGN KEY (IdUsuario) REFERENCES dbo.Usuario(IdUsuario),
    CONSTRAINT FK_Venta_TipoComprobante FOREIGN KEY (IdTipoComprobante) REFERENCES dbo.TipoComprobante(IdTipoComprobante),
    CONSTRAINT FK_Venta_EstadoComprobante FOREIGN KEY (IdEstadoComprobante) REFERENCES dbo.EstadoComprobante(IdEstadoComprobante),
    CONSTRAINT UQ_Venta_Comprobante UNIQUE (Serie, NumeroComprobante)
);
GO

-- DetalleVenta: Líneas de producto de cada venta
CREATE TABLE dbo.DetalleVenta (
    IdDetalleVenta INT NOT NULL CONSTRAINT PK_DetalleVenta PRIMARY KEY,
    IdVenta INT NOT NULL,
    IdProducto INT NOT NULL,
    Cantidad DECIMAL(12,3) NOT NULL,
    PrecioUnitario DECIMAL(12,4) NOT NULL,
    Subtotal DECIMAL(12,2) NOT NULL,
    CONSTRAINT FK_DetalleVenta_Venta FOREIGN KEY (IdVenta) REFERENCES dbo.Venta(IdVenta),
    CONSTRAINT FK_DetalleVenta_Producto FOREIGN KEY (IdProducto) REFERENCES dbo.Producto(IdProducto)
);
GO

-- TipoMovimiento: Tipos de movimiento del kardex
CREATE TABLE dbo.TipoMovimiento (
    IdTipoMovimiento INT NOT NULL CONSTRAINT PK_TipoMovimiento PRIMARY KEY,
    NombreTipoMovimiento NVARCHAR(60) NOT NULL,
    Naturaleza NVARCHAR(10) NOT NULL,
    Signo INT NOT NULL
);
GO

-- MovimientoInventario: Kardex: cada entrada o salida de stock
CREATE TABLE dbo.MovimientoInventario (
    IdMovimiento INT NOT NULL CONSTRAINT PK_MovimientoInventario PRIMARY KEY,
    FechaRegistro DATE NOT NULL,
    HoraRegistro TIME(0) NULL,
    IdAlmacen INT NOT NULL,
    IdProducto INT NOT NULL,
    IdTipoMovimiento INT NOT NULL,
    Cantidad DECIMAL(12,3) NOT NULL,
    StockResultante DECIMAL(12,3) NULL,
    IdVenta INT NULL,
    SerieCompra NVARCHAR(10) NULL,
    NumeroCompra NVARCHAR(15) NULL,
    IdUsuario INT NOT NULL,
    CONSTRAINT FK_MovimientoInventario_Almacen FOREIGN KEY (IdAlmacen) REFERENCES dbo.Almacen(IdAlmacen),
    CONSTRAINT FK_MovimientoInventario_Producto FOREIGN KEY (IdProducto) REFERENCES dbo.Producto(IdProducto),
    CONSTRAINT FK_MovimientoInventario_TipoMovimiento FOREIGN KEY (IdTipoMovimiento) REFERENCES dbo.TipoMovimiento(IdTipoMovimiento),
    CONSTRAINT FK_MovimientoInventario_Venta FOREIGN KEY (IdVenta) REFERENCES dbo.Venta(IdVenta),
    CONSTRAINT FK_MovimientoInventario_Usuario FOREIGN KEY (IdUsuario) REFERENCES dbo.Usuario(IdUsuario)
);
GO

