UNION ALL SELECT N'Material' AS Tabla, COUNT(*) AS Filas FROM dbo.Material
UNION ALL SELECT N'Origen' AS Tabla, COUNT(*) AS Filas FROM dbo.Origen
UNION ALL SELECT N'TipoProducto' AS Tabla, COUNT(*) AS Filas FROM dbo.TipoProducto
UNION ALL SELECT N'Producto' AS Tabla, COUNT(*) AS Filas FROM dbo.Producto
UNION ALL SELECT N'Departamento' AS Tabla, COUNT(*) AS Filas FROM dbo.Departamento
UNION ALL SELECT N'Provincia' AS Tabla, COUNT(*) AS Filas FROM dbo.Provincia
UNION ALL SELECT N'Distrito' AS Tabla, COUNT(*) AS Filas FROM dbo.Distrito
UNION ALL SELECT N'Cliente' AS Tabla, COUNT(*) AS Filas FROM dbo.Cliente
UNION ALL SELECT N'Usuario' AS Tabla, COUNT(*) AS Filas FROM dbo.Usuario
UNION ALL SELECT N'Almacen' AS Tabla, COUNT(*) AS Filas FROM dbo.Almacen
UNION ALL SELECT N'TipoComprobante' AS Tabla, COUNT(*) AS Filas FROM dbo.TipoComprobante
UNION ALL SELECT N'EstadoComprobante' AS Tabla, COUNT(*) AS Filas FROM dbo.EstadoComprobante
UNION ALL SELECT N'Venta' AS Tabla, COUNT(*) AS Filas FROM dbo.Venta
UNION ALL SELECT N'DetalleVenta' AS Tabla, COUNT(*) AS Filas FROM dbo.DetalleVenta
UNION ALL SELECT N'TipoMovimiento' AS Tabla, COUNT(*) AS Filas FROM dbo.TipoMovimiento
UNION ALL SELECT N'MovimientoInventario' AS Tabla, COUNT(*) AS Filas FROM dbo.MovimientoInventario;
